import { getEnumList, getList as _getList, remove } from "@/api/i6000/enum";
import EnumAddEdit from "./components/enum/addedit.vue";
import { setToken } from "@/util/auth";
//成本中心页面
export default {
  name: 'enum',
  components: {
    EnumAddEdit: EnumAddEdit
  },
  data: function data() {
    return {
      tableloading: false,
      queryParams: {},
      page: {
        currentPage: 1,
        pageSize: 20,
        total: 0
      },
      tableData: null,
      showAddEdit: false,
      fromValue: null,
      type: null,
      enumList: null
    };
  },
  mounted: function mounted() {
    this.page = {
      currentPage: 1,
      pageSize: 20,
      total: 0
    };
    this.getList();
    this.initDict();
  },
  methods: {
    initDict: function initDict() {
      var _this = this;
      getEnumList().then(function (res) {
        _this.enumList = res.data;
      });
    },
    getList: function getList() {
      var _this2 = this;
      this.tableloading = true;
      _getList(this.page.currentPage, this.page.pageSize, this.queryParams).then(function (res) {
        var data = res.data;
        _this2.page.total = data.total;
        _this2.tableData = data.records;
        _this2.tableloading = false;
      });
    },
    handelAdd: function handelAdd() {
      this.type = 'add';
      this.showAddEdit = true;
    },
    handleEdit: function handleEdit(row) {
      this.type = 'edit';
      this.showAddEdit = true;
      this.fromValue = row;
    },
    handelDelete: function handelDelete(id) {
      var _this3 = this;
      if (id) {
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(function () {
          return remove(id);
        }).then(function () {
          _this3.getList();
          _this3.$message({
            type: "success",
            message: "删除成功!"
          });
        });
      } else {
        if (this.$refs.table.selection.length === 0) {
          this.$message.warning("请选择至少一条数据");
          return;
        }
        this.$confirm("确定将选择数据删除?", {
          confirmButtonText: "确定",
          cancelButtonText: "取消",
          type: "warning"
        }).then(function () {
          var ids = _this3.$refs.table.selection.map(function (item, index) {
            return item.id;
          }).join(',');
          return remove(ids);
        }).then(function () {
          _this3.getList();
          _this3.$message({
            type: "success",
            message: "操作成功!"
          });
        });
      }
    },
    Nindex: function Nindex(index) {
      return index + 1 + (this.page.currentPage - 1) * this.page.pageSize;
    },
    reset: function reset() {
      this.queryParams = {};
      this.page = {
        currentPage: 1,
        pageSize: 20,
        total: 0
      };
      this.getList();
    },
    getTypeColor: function getTypeColor(type) {
      if (type == '0') {
        return '#209141';
      } else if (type == '1') {
        return '#4390F2';
      } else if (type == '2') {
        return '#000000';
      } else if (type == '3') {
        return '#000000';
      }
      return '#000000';
    },
    getTypeName: function getTypeName(type) {
      if (type == '0') {
        return '属性';
      } else if (type == '1') {
        return '配置项';
      } else if (type == '2') {
        return '模型';
      } else if (type == '3') {
        return '字典模型';
      }
    }
  }
};
